python3 -c '
import unicodedata

items = [
    ["㍞", "㍟", "㍠", "㍡", "㍢", "㍣", "㍤", "㍥"],
    ["🀙", "🀚", "🀛", "🀜"],
    ["🃫", "🃬", "🃭", "🃮", "🃯", "🃰", "🃱", "🃲"],
    ["㏣", "㏤", "㏥", "㏦", "㏧", "㏨", "㏩", "㏪"],
    ["🃡", "🃢", "🃣", "🃤", "🃥", "🃦"]
]

for idx, s in enumerate(items):
    print(f"Item {idx}:")
    for c in s:
        try:
            print(f"  {c} (U+{ord(c):04X}) - {unicodedata.name(c)}")
        except ValueError:
            print(f"  {c} (U+{ord(c):04X}) - No name")

    last_cp = ord(s[-1])
    print("  Next 10:")
    for i in range(1, 11):
        c = chr(last_cp + i)
        try:
            print(f"    {c} (U+{ord(c):04X}) - {unicodedata.name(c)}")
        except ValueError:
            print(f"    {c} (U+{ord(c):04X}) - No name")
'
